// Minimum discovered-place count required for each form.
const uint8_t pet_form_threshold[PET_FORM_COUNT] = {
    [0] = 0,
    [1] = 2,
    [2] = 4,
    [3] = 8,
    [4] = 12,
    [5] = 16,
};

uint8_t pet_form_for_places(uint8_t places)
{
    uint8_t form = 0;
    for (uint8_t i = 0; i < PET_FORM_COUNT; i++) {
        if (places >= pet_form_threshold[i]) {
            form = i;
        }
    }
    return form; // monotonic: callers must never decrease a stored form
}
